internal static partial class Program
{
    // This exact fixture was generated by SnipStudio/checks/video/WriterChecks.cs:
    // 30 painted 640x360 frames at 15 fps and a mathematical 440 Hz PCM tone.
    // It contains no desktop, microphone, loopback, camera or user recording.
    private const string VideoSmokeFixtureSha256 = "C9FCF7337D50D37469FD0944055808C8F2C8279F7989A063F73571AEFEEE0A5A";
    private const int VideoSmokeFixtureBytes = 64190;
    private const int VideoSmokeBudgetSeconds = 50;

    private sealed class VideoSmokeEvidence
    {
        public string? InputSHA256Before { get; set; }
        public string? InputSHA256After { get; set; }
        public bool InputUnchanged { get; set; }
        public bool NativeWorkMayOutliveWait { get; set; }
        public List<object> Steps { get; } = new();
        public List<object> Files { get; } = new();
        public List<object> Metadata { get; } = new();
        public List<object> PreviewPixels { get; } = new();
        public List<object> MemorySamples { get; } = new();
    }

    private static int RunVideoSmoke(string inputPath, string outputDir)
    {
        string output = Path.GetFullPath(outputDir);
        if (Directory.Exists(output) && Directory.EnumerateFileSystemEntries(output).Any())
        {
            Console.Error.WriteLine("Use a new empty synthetic video smoke evidence directory.");
            return 2;
        }
        Directory.CreateDirectory(output);
        var observed = new VideoSmokeEvidence();
        bool passed = false;
        string? failure = null;
        int startingAssertions = assertions;
        Stopwatch clock = Stopwatch.StartNew();
        using var budget = new CancellationTokenSource(TimeSpan.FromSeconds(VideoSmokeBudgetSeconds));
        using StaContext context = new();
        SynchronizationContext.SetSynchronizationContext(context);
        try
        {
            if (!Path.IsPathFullyQualified(inputPath)) throw new ArgumentException("Use the absolute path to the reviewed generated video fixture.");
            observed.InputSHA256Before = VideoSmokeHash(inputPath);
            Check(new FileInfo(inputPath).Length == VideoSmokeFixtureBytes && observed.InputSHA256Before == VideoSmokeFixtureSha256,
                "Input is the exact reviewed generated two-second video, not an arbitrary recording");
            context.Run(CheckVideoSmokeAsync(inputPath, output, observed, budget.Token));
            passed = true;
        }
        catch (Exception error)
        {
            failure = error.ToString();
            Console.Error.WriteLine(failure);
        }
        finally
        {
            budget.Cancel();
            try
            {
                if (observed.InputSHA256Before is not null)
                {
                    observed.InputSHA256After = VideoSmokeHash(inputPath);
                    observed.InputUnchanged = observed.InputSHA256After == observed.InputSHA256Before;
                    if (!observed.InputUnchanged) throw new InvalidOperationException("Synthetic input bytes changed during the smoke check.");
                }
            }
            catch (Exception error)
            {
                passed = false;
                failure = (failure is null ? "" : failure + Environment.NewLine) + error;
            }
            clock.Stop();
            string json = JsonSerializer.Serialize(new
            {
                CheckedUtc = DateTimeOffset.UtcNow,
                Passed = passed,
                Assertions = assertions - startingAssertions,
                ElapsedMilliseconds = clock.Elapsed.TotalMilliseconds,
                AwaitBudgetSeconds = VideoSmokeBudgetSeconds,
                ExpectedInputSHA256 = VideoSmokeFixtureSha256,
                FixtureProvenance = "WriterChecks.cs: 30 generated 640x360/15fps painted frames, red top-left/lime bottom-left markers, and a generated 440Hz stereo tone; no hardware recording.",
                ExportFixtureNote = "The original 64190-byte file is already too compact for the export planner's overhead/budget rule. Positive export uses an owned byte-identical media copy with one explicit 2 MiB MP4 free box appended. A smaller result proves removal/re-encoding of this padded copy, not improved compression of the compact original.",
                Scope = "Actual video metadata, filmstrip, copy, trim, export and frame-decoder adapters; source/copy hashes and failure preservation. Synthetic frame and audio sources exercise the recorder's response to interruption during capture and finalization, and to startup failure. AAC stream presence is checked through metadata. No native WinUI playback, live capture, audio devices, installation or physical monitor acceptance. Waits share a fifty-second budget; synchronous native codec calls may outlive cancellation or timeout.",
                Observations = observed,
                Failure = failure
            }, new JsonSerializerOptions { WriteIndented = true });
            File.WriteAllText(Path.Combine(output, "video-smoke-checks.json"), json, new UTF8Encoding(false));
            Console.WriteLine(json);
            SynchronizationContext.SetSynchronizationContext(null);
        }
        return passed ? 0 : 1;
    }

    private static async Task CheckVideoSmokeAsync(string input, string output, VideoSmokeEvidence observed, CancellationToken budget)
    {
        observed.MemorySamples.Add(SampleMemory("Before local synthetic video codecs"));
        VideoMetadata original = await VideoSmokeStepAsync("Inspect original generated MP4",
            () => VideoReviewService.InspectAsync(input, budget), observed, budget).ConfigureAwait(false);
        RecordVideoSmokeMetadata("original", original, observed);
        Check(original.Width == 640 && original.Height == 360 && original.FramesPerSecond == 15 && original.HasAudio,
            "Generated source metadata preserves 640x360, 15 fps and its AAC stream");
        double durationTolerance = 2.0 / original.FramesPerSecond + .001;
        Check(Math.Abs(original.Duration.TotalSeconds - 2) <= durationTolerance, "Generated source duration is two seconds within two frames");
        double originalBoxCenter = await CheckVideoSmokePreviewAsync(input, "original", TimeSpan.FromSeconds(.4), original, output, observed, budget).ConfigureAwait(false);
        await CheckFilmstripAsync(input, observed, budget).ConfigureAwait(false);

        string copy = Path.Combine(output, "exact-copy.mp4");
        await VideoSmokeStepAsync("Save a byte-exact attachment copy at its size limit",
            () => VideoReviewService.SaveCopyAsync(input, copy, budget, maximumBytes: VideoSmokeFixtureBytes), observed, budget).ConfigureAwait(false);
        Check(VideoSmokeHash(copy) == VideoSmokeFixtureSha256, "An attachment copy at the byte limit preserves every generated source byte");
        RecordVideoSmokeFile(copy, "Exact media copy", observed);

        string trimmed = Path.Combine(output, "trimmed-0.3-to-1.3.mp4");
        await VideoSmokeStepAsync("Trim at non-keyframe boundaries 0.3 to 1.3 seconds",
            () => VideoReviewService.TrimAsync(input, trimmed, TimeSpan.FromSeconds(.3), TimeSpan.FromSeconds(1.3)), observed, budget).ConfigureAwait(false);
        VideoMetadata trimMetadata = await VideoSmokeStepAsync("Inspect trimmed MP4",
            () => VideoReviewService.InspectAsync(trimmed, budget), observed, budget).ConfigureAwait(false);
        RecordVideoSmokeMetadata("trimmed", trimMetadata, observed);
        Check(trimMetadata.Width == original.Width && trimMetadata.Height == original.Height && trimMetadata.FramesPerSecond == 15 && trimMetadata.HasAudio,
            "Trim preserves dimensions, frame rate and audio stream");
        Check(Math.Abs(trimMetadata.Duration.TotalSeconds - 1) <= durationTolerance, "Trim duration matches the one-second range within two source frames");
        RecordVideoSmokeFile(trimmed, "Native one-second trimmed media", observed);
        double trimmedBoxCenter = await CheckVideoSmokePreviewAsync(trimmed, "trimmed", TimeSpan.FromSeconds(.1), trimMetadata, output, observed, budget).ConfigureAwait(false);
        Check(Math.Abs(trimmedBoxCenter - originalBoxCenter) <= 12,
            "Trimmed 0.1-second picture matches the source's 0.4-second moving-box position within one frame and lossy edges");

        string preserved = Path.Combine(output, "opaque-preserved-target.mp4");
        using (var sentinel = new FileStream(preserved, FileMode.CreateNew, FileAccess.Write, FileShare.None))
            sentinel.Write(Encoding.UTF8.GetBytes("Opaque preservation sentinel; this is deliberately not playable video.\n"));
        string preservedHash = VideoSmokeHash(preserved);
        await ExpectAsync<InvalidOperationException>(() => VideoSmokeStepAsync("Refuse an attachment copy one byte over its limit",
            () => VideoReviewService.SaveCopyAsync(input, preserved, budget, maximumBytes: VideoSmokeFixtureBytes - 1), observed, budget),
            "Exact copies honor the target size under the source read lease").ConfigureAwait(false);
        Check(VideoSmokeHash(preserved) == preservedHash && VideoSmokeHash(input) == VideoSmokeFixtureSha256,
            "Rejecting an oversize exact copy preserves existing target and input bytes");

        await ExpectAsync<InvalidOperationException>(() => VideoSmokeStepAsync("Reject compact original export without replacing destination",
            () => VideoReviewService.ExportAsync(input, preserved, original, VideoExportPreset.Small480p, 1, budget), observed, budget),
            "Already-compact original export is honestly rejected by the real planner").ConfigureAwait(false);
        Check(VideoSmokeHash(preserved) == preservedHash && VideoSmokeHash(input) == VideoSmokeFixtureSha256,
            "Rejected compact export preserves existing target and original input exactly");

        // The original MP4 has finite top-level boxes ending at EOF. Appending
        // an explicitly sized ISO BMFF free box leaves its media/offsets intact.
        // This artificial source-size padding is only an export-path fixture.
        const int freeBoxBytes = 2 * 1024 * 1024;
        string padded = Path.Combine(output, "generated-media-with-free-box.mp4");
        byte[] fixture = File.ReadAllBytes(input);
        byte[] freeBox = new byte[freeBoxBytes];
        BinaryPrimitives.WriteUInt32BigEndian(freeBox.AsSpan(0, 4), freeBoxBytes);
        Encoding.ASCII.GetBytes("free", freeBox.AsSpan(4, 4));
        using (var target = new FileStream(padded, FileMode.CreateNew, FileAccess.Write, FileShare.None))
        { target.Write(fixture); target.Write(freeBox); target.Flush(true); }
        byte[] paddedBytes = File.ReadAllBytes(padded);
        Check(paddedBytes.AsSpan(0, fixture.Length).SequenceEqual(fixture) && paddedBytes.Length == fixture.Length + freeBoxBytes,
            "Export fixture retains every original media byte and adds only its declared free box");
        string paddedHash = VideoSmokeHash(padded);
        RecordVideoSmokeFile(padded, "Generated media with explicit artificial MP4 free-box padding", observed);
        VideoMetadata paddedMetadata = await VideoSmokeStepAsync("Inspect padded generated export source",
            () => VideoReviewService.InspectAsync(padded, budget), observed, budget).ConfigureAwait(false);
        RecordVideoSmokeMetadata("padded export source", paddedMetadata, observed);
        Check(paddedMetadata.Width == original.Width && paddedMetadata.Height == original.Height && paddedMetadata.FramesPerSecond == original.FramesPerSecond &&
            paddedMetadata.HasAudio == original.HasAudio && paddedMetadata.Duration == original.Duration,
            "Padding leaves the generated footage's decoded metadata unchanged");

        string exported = Path.Combine(output, "smaller-generated-copy.mp4");
        VideoExportResult exportResult = await VideoSmokeStepAsync("Export owned padded source using Small480p",
            () => VideoReviewService.ExportAsync(padded, exported, paddedMetadata, VideoExportPreset.Small480p, 1, budget), observed, budget).ConfigureAwait(false);
        Check(exportResult.Path == exported && exportResult.Bytes == new FileInfo(exported).Length && exportResult.SourceBytes == paddedBytes.Length,
            "Export result reports the actual destination and exact source/output file lengths");
        Check(exportResult.Bytes > 0 && exportResult.Bytes < exportResult.SourceBytes,
            "Exported MP4 is smaller than the explicitly padded generated source");
        VideoMetadata exportMetadata = await VideoSmokeStepAsync("Inspect exported MP4",
            () => VideoReviewService.InspectAsync(exported, budget), observed, budget).ConfigureAwait(false);
        RecordVideoSmokeMetadata("exported", exportMetadata, observed);
        Check(exportMetadata.Width == original.Width && exportMetadata.Height == original.Height && exportMetadata.FramesPerSecond == 15 && exportMetadata.HasAudio,
            "Small480p retains the already-small source dimensions, frame rate and audio stream");
        Check(Math.Abs(exportMetadata.Duration.TotalSeconds - original.Duration.TotalSeconds) <= durationTolerance,
            "Export preserves the generated media duration within two source frames");
        Check(VideoSmokeHash(padded) == paddedHash, "Export preserves every byte of its owned padded source");
        RecordVideoSmokeFile(exported, "Native smaller padded-source export", observed);
        double exportedBoxCenter = await CheckVideoSmokePreviewAsync(exported, "exported", TimeSpan.FromSeconds(.4), exportMetadata, output, observed, budget).ConfigureAwait(false);
        Check(Math.Abs(exportedBoxCenter - originalBoxCenter) <= 12,
            "Export retains the moving-box position at the original source time within one frame and lossy edges");

        await CheckAttachmentExportAsync(padded, paddedHash, paddedMetadata, paddedBytes.Length, preserved, preservedHash,
            output, observed, budget).ConfigureAwait(false);
        await CheckVideoPublicationRecoveryAsync(padded, paddedMetadata, paddedBytes.Length,
            output, observed, budget).ConfigureAwait(false);

        using var canceled = new CancellationTokenSource();
        canceled.Cancel();
        await ExpectAsync<OperationCanceledException>(() => VideoSmokeStepAsync("Pre-canceled metadata request",
            () => VideoReviewService.InspectAsync(input, canceled.Token), observed, budget), "Pre-canceled inspection is rejected").ConfigureAwait(false);
        await ExpectAsync<OperationCanceledException>(() => VideoSmokeStepAsync("Pre-canceled filmstrip request",
            () => VideoReviewService.ReadFilmstripAsync(input, canceled.Token), observed, budget), "Pre-canceled filmstrip decoding is rejected").ConfigureAwait(false);
        await ExpectAsync<OperationCanceledException>(() => VideoSmokeStepAsync("Pre-canceled save copy preserves destination",
            () => VideoReviewService.SaveCopyAsync(input, preserved, canceled.Token), observed, budget), "Pre-canceled copy is rejected").ConfigureAwait(false);
        await ExpectAsync<OperationCanceledException>(() => VideoSmokeStepAsync("Pre-canceled export preserves destination",
            () => VideoReviewService.ExportAsync(padded, preserved, paddedMetadata, VideoExportPreset.Small480p, 1, canceled.Token), observed, budget),
            "Pre-canceled native export is rejected").ConfigureAwait(false);
        await ExpectAsync<ArgumentException>(() => VideoSmokeStepAsync("Reject reversed trim range without replacing destination",
            () => VideoReviewService.TrimAsync(input, preserved, TimeSpan.FromSeconds(1.3), TimeSpan.FromSeconds(.3)), observed, budget),
            "Reversed trim range is rejected").ConfigureAwait(false);
        await ExpectAsync<ArgumentException>(() => VideoSmokeStepAsync("Reject trim beyond decoded source duration without replacing destination",
            () => VideoReviewService.TrimAsync(input, preserved, TimeSpan.Zero, TimeSpan.FromSeconds(3)), observed, budget),
            "Native metadata validation rejects an out-of-range trim").ConfigureAwait(false);
        Check(VideoSmokeHash(preserved) == preservedHash && VideoSmokeHash(input) == VideoSmokeFixtureSha256 && VideoSmokeHash(padded) == paddedHash,
            "Cancellation and invalid trim retain existing target and both input files exactly");
        using (var locked = new FileStream(preserved, FileMode.Open, FileAccess.Read, FileShare.None))
            await ExpectAsync<IOException>(() => VideoSmokeStepAsync("Locked-target copy fails without replacing existing evidence",
                () => VideoReviewService.SaveCopyAsync(input, preserved, budget), observed, budget), "Locked-target copy reports its save failure").ConfigureAwait(false);
        Check(VideoSmokeHash(preserved) == preservedHash, "Failed atomic copy preserves the existing locked destination bytes");
        Check(!Directory.EnumerateFiles(output, ".snip-video-copy-*").Any(), "Failed copy leaves no partial copy temporary file");
        Check(VideoSmokeHash(input) == VideoSmokeFixtureSha256, "Every successful and failed workflow preserves the original generated MP4");
        RecordVideoSmokeFile(preserved, "Opaque failure/cancellation sentinel, not video", observed);
        await CheckRecorderAudioRecoveryAsync(output, observed, budget).ConfigureAwait(false);
        observed.MemorySamples.Add(SampleMemory("After local synthetic video workflows; sampled, not peak memory"));
    }

    private static async Task CheckAttachmentExportAsync(string source, string sourceHash, VideoMetadata metadata, long sourceBytes,
        string preservedDestination, string preservedHash, string output, VideoSmokeEvidence observed, CancellationToken budget)
    {
        const int targetMegabytes = 1;
        const long targetBytes = targetMegabytes * 1000000L;
        long reportedBytes = await VideoSmokeStepAsync("Read the current source size for export preflight",
            () => VideoReviewService.ReadSourceSizeAsync(source, budget), observed, budget).ConfigureAwait(false);
        Check(reportedBytes == sourceBytes, "Export preflight sees the actual bytes in the owned source");

        var preparation = VideoReviewService.PrepareExport(source, reportedBytes, metadata, VideoExportPreset.TargetAttachmentSize, targetMegabytes);
        Check(preparation.MaximumCopyBytes == null && preparation.EncodingPlan != null, "An oversized MP4 requires re-encoding");
        VideoExportPlan plan = preparation.EncodingPlan!;
        Check(sourceBytes > targetBytes && plan.TargetBytes == targetBytes && plan.EstimatedBytes <= targetBytes && plan.HasAudio,
            "Attachment planner estimates a reduction under the requested decimal MB target and keeps audio");

        foreach (int quickSize in new[] { 10, 20, 25 })
        {
            long limit = quickSize * 1_000_000L;
            var fit = VideoReviewService.PrepareExport("recording.MP4", limit, null, VideoExportPreset.TargetAttachmentSize, quickSize);
            Check(fit.EncodingPlan == null && fit.MaximumCopyBytes == limit,
                $"The {quickSize} MB quick choice copies a fitting MP4 at the exact byte limit without relying on codec metadata");
            var needsEncoding = VideoReviewService.PrepareExport(source, limit + 1, metadata, VideoExportPreset.TargetAttachmentSize, quickSize);
            Check(needsEncoding.EncodingPlan?.TargetBytes == limit && needsEncoding.MaximumCopyBytes == null,
                $"The {quickSize} MB quick choice encodes a video one byte over the limit");
        }
        var otherContainer = VideoReviewService.PrepareExport("recording.webm", sourceBytes, metadata, VideoExportPreset.TargetAttachmentSize, 10);
        Check(otherContainer.EncodingPlan != null && otherContainer.MaximumCopyBytes == null,
            "A fitting non-MP4 uses an MP4 conversion plan rather than a renamed copy");
        Expect<InvalidOperationException>(() => VideoReviewService.PrepareExport("recording.mkv", sourceBytes, null,
            VideoExportPreset.TargetAttachmentSize, 10), "An input needing re-encoding requires readable metadata");
        Expect<ArgumentOutOfRangeException>(() => VideoReviewService.PrepareExport(source, sourceBytes, metadata,
            VideoExportPreset.TargetAttachmentSize, 0), "An invalid attachment cap fails before copying or encoding");

        string email = Path.Combine(output, "email-attachment.mp4");
        VideoExportResult result = await VideoSmokeStepAsync("Encode a strict 1 MB attachment from the owned padded clip",
            () => VideoReviewService.ExportAsync(source, email, plan, budget), observed, budget).ConfigureAwait(false);
        Check(result.Path == email && result.Bytes == new FileInfo(email).Length && result.TargetBytes == targetBytes && result.TargetMet &&
            result.Bytes > 0 && result.Bytes <= targetBytes && result.Bytes < sourceBytes,
            "Attachment export measures the actual smaller MP4 and respects the requested limit");
        VideoMetadata attachment = await VideoSmokeStepAsync("Inspect the email attachment MP4",
            () => VideoReviewService.InspectAsync(email, budget), observed, budget).ConfigureAwait(false);
        Check(attachment.HasAudio && attachment.Width == plan.Width && attachment.Height == plan.Height &&
            Math.Abs((attachment.Duration - metadata.Duration).TotalSeconds) <= 2.0 / metadata.FramesPerSecond + .001,
            "Email MP4 retains the audio stream, planned image size and source duration");
        RecordVideoSmokeFile(email, "Native 1 MB attachment export", observed);
        RecordVideoSmokeMetadata("email attachment", attachment, observed);

        // A one-byte test ceiling forces the post-encode refusal deterministically
        // without relying on codec bitrate variance or invalidating the encode plan.
        plan.TargetBytes = 1;
        InvalidOperationException? overLimit = null;
        try
        {
            await VideoSmokeStepAsync("Reject over-limit attachment before replacing the existing destination",
                () => VideoReviewService.ExportAsync(source, preservedDestination, plan, budget), observed, budget).ConfigureAwait(false);
        }
        catch (InvalidOperationException error) { overLimit = error; }
        Check(overLimit?.Message.Contains("attachment limit", StringComparison.Ordinal) == true,
            "Strict oversize export reports the attachment limit after encoding");
        Check(VideoSmokeHash(preservedDestination) == preservedHash && VideoSmokeHash(source) == sourceHash &&
            !Directory.EnumerateFiles(output, ".snip-trim-*.mp4").Any(),
            "Strict oversize export preserves both files and clears the rejected temporary MP4");

        string legacy = Path.Combine(output, "legacy-over-limit-copy.mp4");
        VideoExportResult legacyResult = await VideoSmokeStepAsync("Keep advisory targets for the legacy export API",
            () => VideoTrimService.ExportAsync(source, legacy, plan, budget, progress: null), observed, budget).ConfigureAwait(false);
        Check(File.Exists(legacy) && !legacyResult.TargetMet && legacyResult.Bytes < sourceBytes &&
            VideoSmokeHash(source) == sourceHash,
            "Legacy export still publishes a smaller copy and reports a missed target");

        // With audio, a 1 MB target supports the minimum video bitrate at 23 s
        // but has an insufficient budget at 24 s for these source dimensions.
        var boundary = new VideoMetadata
        {
            Width = metadata.Width, Height = metadata.Height, FramesPerSecond = metadata.FramesPerSecond,
            HasAudio = true, Duration = TimeSpan.FromSeconds(23)
        };
        VideoExportPlan boundaryPlan = VideoTrimService.CreateExportPlan(boundary, sourceBytes, VideoExportPreset.TargetAttachmentSize, targetMegabytes);
        Check(boundaryPlan.VideoBitrate >= 200000 && boundaryPlan.EstimatedBytes <= targetBytes && boundaryPlan.AudioBitrate == 96000,
            "Feasible attachment target keeps the minimum video and selected audio bitrates");
        boundary.Duration = TimeSpan.FromSeconds(24);
        Expect<InvalidOperationException>(() => VideoTrimService.CreateExportPlan(boundary, sourceBytes, VideoExportPreset.TargetAttachmentSize, targetMegabytes),
            "Planner refuses an attachment duration that cannot meet the minimum bitrate and target");
    }

    private static async Task CheckFilmstripAsync(string path, VideoSmokeEvidence observed, CancellationToken budget)
    {
        byte[][] thumbnails = await VideoSmokeStepAsync("Decode the twelve filmstrip thumbnails",
            () => VideoReviewService.ReadFilmstripAsync(path, budget), observed, budget).ConfigureAwait(false);
        Check(thumbnails.Length == 12, "Filmstrip contains one thumbnail for each time segment");
        var centers = new List<double>(thumbnails.Length);
        foreach (byte[] png in thumbnails)
        {
            using var stream = new MemoryStream(png, writable: false);
            using var thumbnail = new Bitmap(stream);
            Color top = thumbnail.GetPixel(3, 3), bottom = thumbnail.GetPixel(3, thumbnail.Height - 4);
            Check(thumbnail.Width == 176 && thumbnail.Height == 99 && top.R > 150 && top.G < 110 &&
                bottom.G > 130 && bottom.R < 110, "Filmstrip thumbnail preserves the expected scaled size and orientation");
            var bluePixels = Enumerable.Range(0, thumbnail.Width).Where(x =>
            {
                Color color = thumbnail.GetPixel(x, 66);
                return color.B > 150 && color.G > 65 && color.G < 200 && color.R < 90;
            }).ToArray();
            Check(bluePixels.Length >= 12, "Filmstrip thumbnail contains the moving box");
            centers.Add(bluePixels.Average());
        }
        Check(centers.Zip(centers.Skip(1)).All(pair => pair.Second > pair.First) && centers[^1] - centers[0] > 35,
            "Filmstrip thumbnails follow source time and cover the clip instead of repeating one frame");
    }

    private static async Task<double> CheckVideoSmokePreviewAsync(string path, string label, TimeSpan position, VideoMetadata metadata,
        string output, VideoSmokeEvidence observed, CancellationToken budget)
    {
        using VideoPreviewFrame frame = await VideoSmokeStepAsync("Decode " + label + " preview through public codec API",
            () => VideoTrimService.ReadPreviewFrameInfoAsync(path, position, new Size(640, 360), budget), observed, budget,
            late => late.Dispose()).ConfigureAwait(false);
        Check(frame.Image.Width == 640 && frame.Image.Height == 360 && frame.Timestamp >= TimeSpan.Zero && frame.Timestamp <= metadata.Duration,
            label + " preview has the expected decoded size and valid source timestamp");
        Check(Math.Abs((frame.Timestamp - position).TotalSeconds) <= 1.0 / metadata.FramesPerSecond + .01,
            label + " seek decodes within one source frame of the requested position");
        Color top = frame.Image.GetPixel(10, 10), bottom = frame.Image.GetPixel(10, 350);
        int blueCount = 0, blueSum = 0;
        for (int x = 0; x < frame.Image.Width; x++)
        {
            Color pixel = frame.Image.GetPixel(x, 240);
            if (pixel.B > 160 && pixel.G > 70 && pixel.G < 200 && pixel.R < 90) { blueCount++; blueSum += x; }
        }
        Check(blueCount >= 50 && blueCount <= 90, label + " contains the generated moving blue box");
        double blueCenter = (double)blueSum / blueCount;
        observed.PreviewPixels.Add(new { Label = label, RequestedSeconds = position.TotalSeconds, ActualSeconds = frame.Timestamp.TotalSeconds,
            TopLeftArgb = top.ToArgb(), BottomLeftArgb = bottom.ToArgb(), BlueBoxCenterX = blueCenter, BluePixelsOnRow240 = blueCount });
        Check(top.R > 160 && top.G < 100 && top.B < 100 && bottom.G > 130 && bottom.R < 100 && bottom.B < 100,
            label + " decoded pixels retain the synthetic red top/lime bottom markers with lossy-codec tolerance");
        string image = Path.Combine(output, label + "-decoded-preview.png");
        using (var file = new FileStream(image, FileMode.CreateNew, FileAccess.Write, FileShare.None)) frame.Image.Save(file, ImageFormat.Png);
        RecordVideoSmokeFile(image, "Decoded generated frame; no desktop capture", observed);
        return blueCenter;
    }

    private static async Task<T> VideoSmokeStepAsync<T>(string name, Func<Task<T>> action, VideoSmokeEvidence observed,
        CancellationToken budget, Action<T>? discardLateResult = null)
    {
        budget.ThrowIfCancellationRequested();
        Stopwatch clock = Stopwatch.StartNew();
        Task<T>? pending = null;
        bool completed = false;
        try
        {
            pending = action();
            T result = await pending.WaitAsync(budget).ConfigureAwait(false);
            completed = true;
            return result;
        }
        catch (OperationCanceledException) when (budget.IsCancellationRequested)
        {
            if (pending is { IsCompleted: false }) observed.NativeWorkMayOutliveWait = true;
            if (pending is not null) _ = ObserveLateVideoSmokeResultAsync(pending, discardLateResult);
            throw new TimeoutException("The synthetic video smoke check exhausted its shared fifty-second wait budget. Native codec calls are not forcibly aborted.");
        }
        catch (TimeoutException)
        {
            // The metadata adapter also has its own ten-second UI deadline;
            // its observed underlying native read may still be finishing.
            observed.NativeWorkMayOutliveWait = true;
            throw;
        }
        finally
        {
            clock.Stop();
            observed.Steps.Add(new { Name = name, CompletedSuccessfully = completed, Milliseconds = clock.Elapsed.TotalMilliseconds });
        }
    }

    private static async Task VideoSmokeStepAsync(string name, Func<Task> action, VideoSmokeEvidence observed, CancellationToken budget)
    {
        await VideoSmokeStepAsync<object?>(name, async () => { await action().ConfigureAwait(false); return null; }, observed, budget).ConfigureAwait(false);
    }

    private static async Task ObserveLateVideoSmokeResultAsync<T>(Task<T> pending, Action<T>? discard)
    {
        try { T result = await pending.ConfigureAwait(false); discard?.Invoke(result); }
        catch (Exception) { }
    }

    private static string VideoSmokeHash(string path)
    {
        using var file = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read);
        return Convert.ToHexString(SHA256.HashData(file));
    }

    private static void RecordVideoSmokeFile(string path, string purpose, VideoSmokeEvidence observed)
    {
        long length = new FileInfo(path).Length;
        Check(length > 0 && length < 8 * 1024 * 1024, "Owned synthetic evidence file has a bounded local size: " + Path.GetFileName(path));
        observed.Files.Add(new { File = Path.GetFileName(path), Purpose = purpose, Bytes = length, SHA256 = VideoSmokeHash(path) });
    }

    private static void RecordVideoSmokeMetadata(string label, VideoMetadata metadata, VideoSmokeEvidence observed) =>
        observed.Metadata.Add(new { Label = label, metadata.Width, metadata.Height, metadata.FramesPerSecond, metadata.HasAudio,
            DurationSeconds = metadata.Duration.TotalSeconds });
}
